#!/usr/bin/env python3
"""Loopback path translator in front of the author's surogate engine (JevBench intake wave m6, Rune v3 text track).

The engine's decisions v1 endpoint (POST /v1/decisions; docs/inference/decisions.md) takes exactly the TypeSafe request that
JevBench's unchanged `typesafe` adapter sends ({model, state, questions: {name: {type, instructions, criteria}}}) and answers
in the TypeSafe shape the adapter reads (answers.<name>: noul = P(true); choice + probabilities keyed by option key; score +
probabilities keyed "0".."k-1"; usage.input_tokens). Only the path differs (/v1/systemone). This proxy forwards the body
byte-for-byte to /v1/decisions and returns the engine's answer byte-for-byte; it changes nothing else. An HTTP 400 (the
engine's refusal of a malformed or over-long request) is returned as 422 (a wrong answer under the harness stop rule); every
other status passes through. GET /health mirrors the engine's /health. Standard library only; binds 127.0.0.1; logs no
request content.
"""
from __future__ import annotations

import sys
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer

UPSTREAM = sys.argv[1].rstrip("/")   # the engine on loopback, e.g. http://127.0.0.1:8000
PORT = int(sys.argv[2])


def forward(method: str, path: str, data: bytes | None) -> tuple[int, bytes]:
    req = urllib.request.Request(UPSTREAM + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"} if data is not None else {})
    try:
        with urllib.request.urlopen(req, timeout=300) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def log_message(self, *args):  # no request lines, no bodies
        pass

    def _send(self, code: int, data: bytes) -> None:
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path != "/health":
            return self._send(404, b'{"error": "not found"}')
        try:
            return self._send(*forward("GET", "/health", None))
        except Exception:  # noqa: BLE001 - not ready yet
            return self._send(503, b'{"ok": false}')

    def do_POST(self):
        if self.path != "/v1/systemone":
            return self._send(404, b'{"error": "not found"}')
        body = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        try:
            status, data = forward("POST", "/v1/decisions", body)
        except Exception:  # noqa: BLE001 - engine unreachable
            return self._send(502, b'{"error": "engine unreachable"}')
        self._send(422 if status == 400 else status, data)


if __name__ == "__main__":
    print("SUROGATE_PROXY_READY", flush=True)
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()
